154	OrcaWorkspaceAdapter::SliceState OrcaWorkspaceAdapter::current_slice_state() const
155	{
156	    SliceState state;
157	    // Whether a slice is running is part of what the plate holds, not merely
158	    // progress: starting one on an already-invalid plate changes neither the
159	    // valid flag nor the result id, so without it that transition publishes
160	    // nothing and no consumer ever learns the slice began.
161	    const bool slicing = m_plater.is_background_process_slicing();
162	    PartPlateList& plates = m_plater.get_partplate_list();
163	    for (int index = 0; index < plates.get_plate_count(); ++index) {
164	        PartPlate* plate = plates.get_plate(index);
165	        if (plate == nullptr) continue;
166	        const bool sliced = plate->is_slice_result_valid();
167	        const std::uint64_t result = sliced && !slicing && plate->get_slice_result() ?
168	            plate->get_slice_result()->id : 0;
169	        state.emplace(plate->id().id, PlateSlice{sliced, result, slicing});
170	    }
171	    return state;
172	}
173	
174	void OrcaWorkspaceAdapter::on_slice_status_changed(wxCommandEvent& event)
175	{
176	    event.Skip();
177	    wxASSERT(wxIsMainThread());
178	    // This event also fires whenever the native toolbar re-evaluates whether
179	    // Slice and Print are enabled, which happens on ordinary selection and
180	    // object changes. Publishing on all of those would advance the revision --
181	    // and add a history entry -- for nothing. Only a real change in what the
182	    // plates hold is a workspace change.
183	    SliceState state = current_slice_state();
184	    if (state == m_known_slice_state)
185	        return;
186	    // A plate that held a slice and no longer does was invalidated by whatever
187	    // the person just did. Recording it here, at the transition, is the only
188	    // moment the cause is still known.
189	    for (const auto& [id, now] : state) {
190	        const auto before = m_known_slice_state.find(id);
191	        if (before != m_known_slice_state.end() && before->second.sliced && !now.sliced)
192	            m_invalidated_by[id] = m_last_change_reason;
193	        else if (now.sliced)
194	            m_invalidated_by.erase(id);
195	    }
196	    m_known_slice_state = std::move(state);
197	    publish_change(WorkspaceChangeReasons::Plates);
198	}
