192	void ProjectPersistence::resolve_pending_boundary()
193	{
194	    if (m_in_revert)
195	        return;
196	    if (heal_if_directory_moved())
197	        return;
198	    if (!m_boundary_pending)
199	        return;
200	    m_boundary_pending = false;
201	    adopt_current_project(/*in_place_reset=*/true);
202	}
203	
204	void ProjectPersistence::adopt_current_project(bool in_place_reset)
205	{
206	    m_attached_aux_dir = m_workspace.auxiliary_data_dir();
207	    m_attached         = true;
208	    m_draft.clear();
209	
210	    if (in_place_reset) {
211	        // A full in-place reset is a new project boundary: earlier state does
212	        // not carry into it.
213	        std::error_code ec;
214	        fs::remove_all(jusprin_data_dir(), ec);
215	        start_fresh_identity();
216	        return;
217	    }
218	
219	    const std::string state_text = read_file(state_file_path());
220	    if (state_text.empty()) {
221	        start_fresh_identity();
222	        return;
223	    }
224	
225	    ProjectStateDocument loaded;
226	    const ProjectStateDocument::LoadResult result = loaded.load(state_text);
227	    if (result == ProjectStateDocument::LoadResult::Corrupt) {
228	        // Keep the unreadable file for inspection, then start over.
229	        std::error_code ec;
230	        fs::rename(state_file_path(), state_file_path() + ".corrupt", ec);
231	        start_fresh_identity();
232	        return;
233	    }
234	    m_document = std::move(loaded);
235	
236	    // The recovery mirror may hold state newer than the last explicit save
237	    // (messages, approvals, a partial reply from before a crash).
238	    const std::string recovery = recovery_dir();
239	    if (!recovery.empty()) {
240	        const std::string mirror_text = read_file(fs::path(recovery) / kStateFileName);
241	        if (!mirror_text.empty()) {
242	            ProjectStateDocument mirror;
243	            if (mirror.load(mirror_text) != ProjectStateDocument::LoadResult::Corrupt &&
244	                mirror.project_id() == m_document.project_id() && mirror.doc_revision() > m_document.doc_revision())
245	                m_document = std::move(mirror);
246	        }
247	        load_recovery_meta();
248	    }
249	
250	    // A stream or run interrupted by the crash/restart cannot resume.
251	    m_document.normalize_interrupted_state();
252	
253	    m_dirty = true;
254	    flush();
255	    notify_document_replaced();
256	}
257	
258	void ProjectPersistence::notify_document_replaced()
259	{
260	    if (m_document_replaced)
261	        m_document_replaced();
262	    // A replaced document brings a different manufacturing ledger with it.
263	    notify_ledger_changed();
264	}
265	
266	void ProjectPersistence::start_fresh_identity()
267	{
268	    m_document = ProjectStateDocument();
269	    m_document.initialize_identity("p-" + m_config.uuid(), "l-" + m_config.uuid(), m_config.clock());
270	    capture_revision("initial");
271	    // Adoption can run before the canvas is able to render (early startup);
272	    // the project content stays equal to the initial state until the first
273	    // manufacturing change, so the capture can be retried until then.
274	    m_initial_capture_pending = m_document.revisions().back().snapshot_file.empty();
275	    m_dirty = true;
276	    flush();
277	    notify_document_replaced();
278	}
279	
280	void ProjectPersistence::retry_initial_capture()
281	{
282	    const std::vector<RevisionInfo> revisions = m_document.revisions();
283	    if (revisions.empty() || !revisions.front().snapshot_file.empty() ||
284	        m_document.current_revision_id() != revisions.front().id) {
285	        m_initial_capture_pending = false;
286	        return;
287	    }
288	    const RevisionInfo& initial  = revisions.front();
289	    const std::string   relative = std::string(kRevisionsDir) + "/" + initial.id + kSnapshotSuffix;
290	    const fs::path      target   = fs::path(jusprin_data_dir()) / kRevisionsDir / (initial.id + kSnapshotSuffix);
291	    std::error_code ec;
292	    fs::create_directories(target.parent_path(), ec);
293	    if (!m_workspace.export_project_archive(target.string()).succeeded())
294	        return; // still not ready; keep retrying on later events
295	    m_initial_capture_pending = false;
296	    ++m_stats.captures;
297	    m_stats.total_snapshot_bytes += fs::file_size(target, ec);
298	    m_document.set_revision_snapshot(initial.id, relative);
299	    m_dirty = true;
300	    flush();
301	}
302	
303	void ProjectPersistence::capture_revision(const std::string& cause)
304	{
305	    const std::string revision_id = m_document.peek_next_revision_id();
306	    const std::string relative    = std::string(kRevisionsDir) + "/" + revision_id + kSnapshotSuffix;
307	    const fs::path    target      = fs::path(jusprin_data_dir()) / kRevisionsDir / (revision_id + kSnapshotSuffix);
308	
309	    std::error_code ec;
310	    fs::create_directories(target.parent_path(), ec);
311	
312	    const auto started = std::chrono::steady_clock::now();
313	    const Workspace::CommandResult exported = m_workspace.export_project_archive(target.string());
314	    m_stats.last_capture_ms =
315	        std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - started).count();
316	
317	    std::string snapshot_file;
318	    if (exported.succeeded()) {
319	        snapshot_file = relative;
320	        ++m_stats.captures;
321	        m_stats.total_snapshot_bytes += fs::file_size(target, ec);
322	    } else {
323	        // Record the revision honestly without a checkpoint; it cannot be
324	        // reverted to, but the timeline stays truthful.
325	        ++m_stats.capture_failures;
326	    }
327	
328	    const RevisionInfo revision = [&] {
329	        const std::string id = m_document.add_revision(cause, snapshot_file, m_document.active_conversation_id(),
330	                                                       m_config.clock());
331	        return *m_document.find_revision(id);
332	    }();
333	    m_dirty = true;
334	    flush();
335	    if (m_revision_added)
336	        m_revision_added(revision);
337	}
338	
339	void ProjectPersistence::flush()
340	{
341	    // Never write a stale document across an unresolved project boundary.
342	    resolve_pending_boundary();
343	    if (!m_attached)
344	        return;
345	    write_state_to(jusprin_data_dir());
346	    const std::string recovery = recovery_dir();
347	    if (!recovery.empty()) {
348	        write_state_to(recovery);
349	        write_recovery_meta();
350	    }
351	    m_dirty = false;
352	}
353	
354	void ProjectPersistence::flush_if_dirty()
355	{
356	    if (m_dirty)
357	        flush();
358	}
359	
360	void ProjectPersistence::write_state_to(const std::string& directory) const
361	{
362	    write_file(fs::path(directory) / kStateFileName, m_document.dump());
363	}
364	
365	void ProjectPersistence::set_draft(const std::string& text)
366	{
367	    if (m_draft == text)
368	        return;
369	    m_draft = text;
370	    write_recovery_meta();
371	}
372	
373	void ProjectPersistence::write_recovery_meta() const
374	{
375	    const std::string recovery = recovery_dir();
376	    if (recovery.empty())
377	        return;
378	    write_file(fs::path(recovery) / kRecoveryMeta,
379	               json{{"draft", m_draft}, {"updatedAt", m_config.clock()}}.dump(2));
380	}
381	
382	void ProjectPersistence::load_recovery_meta()
383	{
384	    const std::string recovery = recovery_dir();
385	    if (recovery.empty())
386	        return;
387	    const json meta = json::parse(read_file(fs::path(recovery) / kRecoveryMeta), nullptr, false);
388	    if (meta.is_object())
389	        m_draft = meta.value("draft", "");
